/**
 * Config desde nodo Set. Soporta: [] vacío, array en 1 ítem, o n ítems (n8n partió el JSON).
 */
const cfg = $('Config Supabase (editar)').first().json;
const items = $input.all();
let rows = [];
if (items.length === 0) {
  rows = [];
} else if (items.length === 1) {
  const raw = items[0].json;
  if (Array.isArray(raw)) rows = raw;
  else if (Array.isArray(raw.body)) rows = raw.body;
  else if (raw && typeof raw === 'object' && raw.data && Array.isArray(raw.data)) rows = raw.data;
  else if (raw && raw.id != null && raw.fecha_cita != null) rows = [raw];
} else {
  rows = items.map((i) => i.json).filter((r) => r && r.id != null);
}

const map = new Map();
const solo = (cfg.telegram_dt_un_solo_usuario || '').trim();
if (solo) {
  const [tg, aid] = solo.split(':').map((s) => s.trim());
  const tgId = parseInt(tg, 10);
  const asesorId = parseInt(aid, 10);
  if (!isNaN(tgId) && !isNaN(asesorId)) {
    map.set(asesorId, [tgId]);
  }
}
const rawMap = (cfg.telegram_asesor_map || '');
for (const part of rawMap.split(',')) {
  const trimmed = part.trim();
  if (!trimmed) continue;
  const [tg, aid] = trimmed.split(':').map((s) => s.trim());
  const tgId = parseInt(tg, 10);
  const asesorId = parseInt(aid, 10);
  if (isNaN(tgId) || isNaN(asesorId)) continue;
  const list = map.get(asesorId) || [];
  if (!list.includes(tgId)) list.push(tgId);
  map.set(asesorId, list);
}

const TZ = 'America/Argentina/Buenos_Aires';
function buildText(c) {
  const when = new Date(c.fecha_cita);
  const fechaStr = when.toLocaleString('es-AR', {
    timeZone: TZ,
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
  });
  const cli = c.cliente_nombre ? `\nCliente: ${c.cliente_nombre}` : '';
  const ficha = c.ficha_numero ? `\nFicha: ${c.ficha_numero}` : '';
  const dur = c.duracion_minutos ? `\nDuración: ${c.duracion_minutos} min` : '';
  const dir = c.direccion ? `\n📍 ${c.direccion}` : '';
  const link = c.ubicacion_link ? `\n🗺 ${c.ubicacion_link}` : '';
  return (
    `⏰ En 30 minutos tenés una cita (DT / Plotlab)\n\n` +
    `📌 ${c.titulo || ''}\n` +
    `🕐 ${fechaStr}${cli}${ficha}${dur}${dir}${link}\n\n` +
    `Recordatorio automático (Plotlab)`
  );
}

const out = [];
for (const c of rows) {
  const chats = map.get(c.id_asesor) || [];
  for (const chatId of chats) {
    out.push({
      json: {
        ...c,
        _cita_id: c.id,
        _telegram_chat_id: chatId,
        _texto: buildText(c),
      },
    });
  }
}
return out;

// Telegram devuelve la respuesta de la API, NO trae id de la cita.
// Recuperamos el ítem emparejado de "Mapear chats + texto".
const m = $('Mapear chats + texto').item.json;
if (m == null || m._cita_id == null) {
  throw new Error('Falta _cita_id: revisá Mapear chats + texto y el mapa telegram_asesor_map');
}
return [{ json: { cita_id: m._cita_id } }];
